/* Byte-order helpers libmtp's ptp code expects (normally generated by its
 * configure script, m4/byteorder.m4). Written for Chinotto's build; both
 * supported targets (x86-64, arm64) are little-endian. */
#ifndef GPHOTO2_ENDIAN_H
#define GPHOTO2_ENDIAN_H

#include <stdint.h>

#if defined(__APPLE__)
#include <libkern/OSByteOrder.h>
#define swap16(x) OSSwapInt16(x)
#define swap32(x) OSSwapInt32(x)
#define swap64(x) OSSwapInt64(x)
#else
#include <byteswap.h>
#define swap16(x) bswap_16(x)
#define swap32(x) bswap_32(x)
#define swap64(x) bswap_64(x)
#endif

#if !defined(__BYTE_ORDER__) || __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error "Chinotto's libmtp build assumes a little-endian CPU"
#endif

#ifndef htole16
#define htole16(x) ((uint16_t)(x))
#define htole32(x) ((uint32_t)(x))
#define htole64(x) ((uint64_t)(x))
#define le16toh(x) ((uint16_t)(x))
#define le32toh(x) ((uint32_t)(x))
#define le64toh(x) ((uint64_t)(x))
#define htobe16(x) swap16(x)
#define htobe32(x) swap32(x)
#define htobe64(x) swap64(x)
#define be16toh(x) swap16(x)
#define be32toh(x) swap32(x)
#define be64toh(x) swap64(x)
#endif

/* Unaligned access to byte arrays. */
#define be16atoh(x) ((uint16_t)(((x)[0] << 8) | (x)[1]))
#define be32atoh(x) ((uint32_t)(((uint32_t)(x)[0] << 24) | ((uint32_t)(x)[1] << 16) | ((uint32_t)(x)[2] << 8) | (x)[3]))
#define be64atoh(x) (((uint64_t)be32atoh(x) << 32) | be32atoh((x) + 4))
#define le16atoh(x) ((uint16_t)(((x)[1] << 8) | (x)[0]))
#define le32atoh(x) ((uint32_t)(((uint32_t)(x)[3] << 24) | ((uint32_t)(x)[2] << 16) | ((uint32_t)(x)[1] << 8) | (x)[0]))
#define le64atoh(x) (((uint64_t)le32atoh((x) + 4) << 32) | le32atoh(x))

#define htobe16a(a, x) ((a)[0] = (uint8_t)((x) >> 8), (a)[1] = (uint8_t)(x))
#define htobe32a(a, x) ((a)[0] = (uint8_t)((x) >> 24), (a)[1] = (uint8_t)((x) >> 16), (a)[2] = (uint8_t)((x) >> 8), (a)[3] = (uint8_t)(x))
#define htobe64a(a, x) (htobe32a((a), (uint32_t)((x) >> 32)), htobe32a((a) + 4, (uint32_t)(x)))
#define htole16a(a, x) ((a)[1] = (uint8_t)((x) >> 8), (a)[0] = (uint8_t)(x))
#define htole32a(a, x) ((a)[3] = (uint8_t)((x) >> 24), (a)[2] = (uint8_t)((x) >> 16), (a)[1] = (uint8_t)((x) >> 8), (a)[0] = (uint8_t)(x))
#define htole64a(a, x) (htole32a((a) + 4, (uint32_t)((x) >> 32)), htole32a((a), (uint32_t)(x)))

#endif
